public static final Cls Shaded = cls("Shaded", Node, C_Shaded::define);
static final class C_Shaded {
  static void define(Cls c) {
    c.statik("literal", (self, a1) -> {
      Object[] n_0 = { arg(a1, 0) };
      if (truthy(!eq(n_0[0], n_0[0]))) {
        if (true) return "1e30";
      }
      if (truthy(gt(m_abs(n_0[0]), power(10.0, 300.0)))) {
        if (true) return (truthy(lt(n_0[0], 0.0)) ? (Object) "(-1e30)" : (Object) "1e30");
      }
      if (truthy((truthy(eq(n_0[0], m_floor(n_0[0]))) && truthy(lt(m_abs(n_0[0]), 1000000000.0))))) {
        if (true) return "(" + str(n_0[0]) + ".0)";
      }
      if (true) return "(" + str(n_0[0]) + ")";
      return null;
    });
    c.statik("wgsl", (self, a1) -> {
      Object[] e_0 = { arg(a1, 0) }; Object[] names_0 = { arg(a1, 1) }; Object[] bound_0 = { arg(a1, 2) };
      Object[] k_0 = new Object[1]; k_0[0] = get(e_0[0], "kind");
      if (truthy(eq(k_0[0], "num"))) {
        if (true) return call(K("Shaded"), "literal", new Object[] { get(e_0[0], "value") });
      }
      if (truthy((truthy(eq(k_0[0], "sym")) || truthy(eq(k_0[0], "field"))))) {
        if (truthy((truthy(!eq(bound_0[0], null)) && truthy(eq(get(e_0[0], "label"), bound_0[0]))))) {
          if (true) return "x";
        }
        Object[] i_0 = new Object[1]; i_0[0] = m_index_of(names_0[0], get(e_0[0], "label"));
        if (truthy(eq(i_0[0], null))) {
          invoke(fail, new Object[] { "the law stands on " + str(get(e_0[0], "label")) + ", which the sweep does not bind" });
        }
        if (true) return "e[" + str(i_0[0]) + "]";
      }
      if (truthy(eq(k_0[0], "add"))) {
        Object[] parts_0 = new Object[1]; parts_0[0] = m_map(get(e_0[0], "of"), (Fn) (a3) -> {
          Object[] x_2 = { arg(a3, 0) };
          if (true) return call(K("Shaded"), "wgsl", new Object[] { x_2[0], names_0[0], bound_0[0] });
          return null;
        });
        Object[] summed_0 = new Object[1]; summed_0[0] = m_join(parts_0[0], " + ");
        if (true) return "(" + str(summed_0[0]) + ")";
      }
      if (truthy(eq(k_0[0], "mul"))) {
        Object[] parts_0 = new Object[1]; parts_0[0] = m_map(get(e_0[0], "of"), (Fn) (a3) -> {
          Object[] x_2 = { arg(a3, 0) };
          if (true) return call(K("Shaded"), "wgsl", new Object[] { x_2[0], names_0[0], bound_0[0] });
          return null;
        });
        Object[] multiplied_0 = new Object[1]; multiplied_0[0] = m_join(parts_0[0], " * ");
        if (true) return "(" + str(multiplied_0[0]) + ")";
      }
      if (truthy(eq(k_0[0], "pow"))) {
        Object[] base_0 = new Object[1]; base_0[0] = call(K("Shaded"), "wgsl", new Object[] { get(e_0[0], "base"), names_0[0], bound_0[0] });
        if (truthy(eq(get(get(e_0[0], "power"), "kind"), "num"))) {
          Object[] n_0 = new Object[1]; n_0[0] = get(get(e_0[0], "power"), "value");
          if (truthy(eq(n_0[0], 0.5))) {
            if (true) return "sqrt(" + str(base_0[0]) + ")";
          }
          if (truthy((truthy(eq(n_0[0], m_floor(n_0[0]))) && truthy(le(m_abs(n_0[0]), 64.0))))) {
            if (true) return "powi(" + str(base_0[0]) + ", " + str(m_round(n_0[0])) + ")";
          }
          if (true) return "pow(" + str(base_0[0]) + ", " + str(call(K("Shaded"), "literal", new Object[] { n_0[0] })) + ")";
        }
        if (true) return "pow(" + str(base_0[0]) + ", " + str(call(K("Shaded"), "wgsl", new Object[] { get(e_0[0], "power"), names_0[0], bound_0[0] })) + ")";
      }
      if (truthy(eq(k_0[0], "log"))) {
        if (true) return "log(" + str(call(K("Shaded"), "wgsl", new Object[] { get(e_0[0], "base"), names_0[0], bound_0[0] })) + ")";
      }
      if (truthy(eq(k_0[0], "exp"))) {
        if (true) return "exp(" + str(call(K("Shaded"), "wgsl", new Object[] { get(e_0[0], "base"), names_0[0], bound_0[0] })) + ")";
      }
      if (truthy(eq(k_0[0], "choose"))) {
        if (true) return "choose(" + str(call(K("Shaded"), "wgsl", new Object[] { get(e_0[0], "first_"), names_0[0], bound_0[0] })) + ", " + str(call(K("Shaded"), "wgsl", new Object[] { get(e_0[0], "second_"), names_0[0], bound_0[0] })) + ")";
      }
      if (true) return invoke(fail, new Object[] { "a " + str(k_0[0]) + " cannot be written as shader code - only a root at the top of a law is solved there" });
      return null;
    });
    c.statik("helpers", (self, a1) -> {
      if (true) return "fn powi(b: f32, n: i32) -> f32 {\n  var r: f32 = 1.0;\n  let m: i32 = abs(n);\n  for (var i: i32 = 0; i < m; i = i + 1) { r = r * b; }\n  if (n < 0) { return 1.0 / r; }\n  return r;\n}\nfn choose(n: f32, k: f32) -> f32 {\n  var r: f32 = 1.0;\n  var i: f32 = 0.0;\n  for (var c: i32 = 0; c < 64; c = c + 1) { if (i < k) { r = r * (n - i) / (i + 1.0); i = i + 1.0; } }\n  return r;\n}\nfn finite(v: f32) -> bool { return abs(v) < 1e30 && v == v; }";
      return null;
    });
    c.statik("points", (self, a1) -> {
      Object[] points_0 = new Object[1]; points_0[0] = list();
      Object[] i_0 = new Object[1]; i_0[0] = 1.0;
      while (truthy(le(i_0[0], 120.0))) {
        m_push(points_0[0], div(i_0[0], 120.0));
        i_0[0] = add(i_0[0], 1.0);
      }
      Object[] ex_0 = new Object[1]; ex_0[0] = 0.0;
      while (truthy(le(ex_0[0], 24.0))) {
        Object[] k_0 = new Object[1]; k_0[0] = 1.0;
        while (truthy(lt(k_0[0], 8.0))) {
          m_push(points_0[0], mul((power(10.0, (sub(ex_0[0], 12.0)))), (add(1.0, div(k_0[0], 2.0)))));
          k_0[0] = add(k_0[0], 1.0);
        }
        ex_0[0] = add(ex_0[0], 1.0);
      }
      if (true) return call(K("Expr"), "sorted", new Object[] { points_0[0] });
      return null;
    });
    c.statik("solver", (self, a1) -> {
      Object[] name_0 = { arg(a1, 0) }; Object[] f_0 = { arg(a1, 1) };
      Object[] pts_0 = new Object[1]; pts_0[0] = get(K("Shaded"), "points");
      Object[] lits_0 = new Object[1]; lits_0[0] = m_join(m_map(pts_0[0], (Fn) (a3) -> {
        Object[] v_2 = { arg(a3, 0) };
        if (true) return call(K("Shaded"), "literal", new Object[] { v_2[0] });
        return null;
      }), ", ");
      if (true) return "const PTS_" + str(name_0[0]) + ": array<f32, " + str(len(pts_0[0])) + "> = array<f32, " + str(len(pts_0[0])) + ">(" + str(lits_0[0]) + ");\nfn " + str(name_0[0]) + "() -> f32 {\n  var lo: f32 = 0.0;\n  var hi: f32 = 0.0;\n  var found: bool = false;\n  var px: f32 = PTS_" + str(name_0[0]) + "[0];\n  var pf: f32 = " + str(f_0[0]) + "(px);\n  for (var j: i32 = 1; j < " + str(len(pts_0[0])) + "; j = j + 1) {\n    let cx: f32 = PTS_" + str(name_0[0]) + "[j];\n    let cf: f32 = " + str(f_0[0]) + "(cx);\n    if (!found && finite(pf) && finite(cf) && pf * cf <= 0.0) { lo = px; hi = cx; found = true; }\n    px = cx;\n    pf = cf;\n  }\n  if (!found) { return 1e30; }\n  var flo: f32 = " + str(f_0[0]) + "(lo);\n  for (var n: i32 = 0; n < 60; n = n + 1) {\n    let mid: f32 = (lo + hi) / 2.0;\n    let fm: f32 = " + str(f_0[0]) + "(mid);\n    if (!finite(fm)) { break; }\n    if (flo * fm <= 0.0) { hi = mid; } else { lo = mid; flo = fm; }\n  }\n  return (lo + hi) / 2.0;\n}";
      return null;
    });
  }
}

public static final Cls Sweep = cls("Sweep", Node, C_Sweep::define);
